#pragma once

#include <stdint.h>

/*
 * Gamate photographic bezel prepared from the user-supplied 922x573 image.
 *
 * The 480x360 central crop is resampled once, offline, to the exact VGA wire
 * geometry: 640 RGB222 samples x 240 stored rows (each stored row is displayed
 * twice). There is no runtime photo scaling. A fine 4x4 ordered quantizer is
 * applied only at the physical 640-sample resolution; unlike the old 320-pixel
 * pair dithering it does not throw away half of the source's horizontal detail.
 *
 * The live 160x150 LCD uses an exact isotropic 6/5 scale: 192x180.
 * LCD rows store only the two photographic side spans.
 */

enum {
    GAMATE_PHOTO_WIDTH_BYTES = 640,
    GAMATE_PHOTO_HEIGHT = 240,
    GAMATE_PHOTO_SCREEN_X_BYTES = 132,
    GAMATE_PHOTO_SCREEN_Y = 32,
    GAMATE_PHOTO_SCREEN_W_PAIRS = 192,
    GAMATE_PHOTO_SCREEN_H = 180,
    GAMATE_PHOTO_RIGHT_BYTES = 124,
    GAMATE_PHOTO_SIDE_BYTES = 256,
    GAMATE_PHOTO_OUTSIDE_ROWS = 60,
};

